-- 475: Original BrillaPrep Cambridge A-Level Biology (9700) Ecology and Nutrient Cycles calculation questions (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_475_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_475_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_ecology_s2_012', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a grassland survey, students caught and marked 96 grasshoppers, then released them. The next day they caught a second sample of 84 grasshoppers, of which 12 were marked. Using the Lincoln index, estimate the size of the grasshopper population.', 'calculation', NULL, NULL, '672 grasshoppers', 'The Lincoln index is N = (n1 × n2) ÷ m, where n1 = number caught, marked and released = 96, n2 = number caught in the second sample = 84, and m = marked individuals recaptured = 12. Substituting: N = (96 × 84) ÷ 12 = 8064 ÷ 12 = 672. The estimated population is therefore 672 grasshoppers. The estimate assumes that no births, deaths, immigration or emigration occurred between the samples, that the marks were not lost, and that marked individuals mixed randomly and were just as likely to be caught as unmarked ones.', 'medium', '5', '3', '240', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_ecology_s2_013', 'topic_alevel_bio_ecology', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'In a lake ecosystem, the producers fix 9.0 × 10⁴ kJ m⁻² yr⁻¹ as gross primary productivity and lose 5.4 × 10⁴ kJ m⁻² yr⁻¹ in respiration. The primary consumers assimilate 4.32 × 10³ kJ m⁻² yr⁻¹. Calculate the net primary productivity of the producers and the percentage efficiency of energy transfer from the producers to the primary consumers.', 'calculation', NULL, NULL, 'NPP = 3.6 × 10⁴ kJ m⁻² yr⁻¹; transfer efficiency = 12%', 'Net primary productivity is gross primary productivity minus respiration losses: NPP = (9.0 × 10⁴) − (5.4 × 10⁴) = 3.6 × 10⁴ kJ m⁻² yr⁻¹. Transfer efficiency = (energy assimilated by primary consumers ÷ NPP) × 100 = (4.32 × 10³ ÷ 3.6 × 10⁴) × 100 = 0.12 × 100 = 12%. The efficiency must be calculated against NPP, not GPP, because only net production is available to herbivores; using GPP would wrongly give 4.8%.', 'hard', '5', '3', '240', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_475_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_475_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_475_guard;
INSERT INTO _migration_475_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_475_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_475_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_475_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_475_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_475_guard;
INSERT INTO _migration_475_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_475_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 2 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_475_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 2 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_475_expected e ON e.id = q.id) = 2 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_475_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
DROP TABLE _migration_475_guard;
